package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Gudun Hijira Daga Mugun Makwabci", "Ya Allah ina neman tsarinka daga muguwar makwabci a wurin zama na dindindin, domin makwabci yana tafiya.", "Domin kariya daga mugun makwabci.", "Annabi ﷺ yayi umarni da neman tsari daga wannan."),
        "dua_ishfi_abdak" to DuaText("Domin Farfadowar Marasa Lafiya", "Ya Allah ka warkar da bawanka domin ya fuskanci makiyi gareka ko ya yi tattaki zuwa ga addu'a dominka.", "Ga mara lafiya lokacin ziyartarsa.", "Annabi ﷺ ya koyar da cewa ga marasa lafiya."),
        "dua_la_mania" to DuaText("Babu wanda zai iya riƙe abin da kuke bayarwa", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma gõdiya ta tabbata, kuma Shĩ, a kan kõme, Mai ĩkon yi ne. Ya Allah, babu mai hana abin da ka bayar, kuma babu mai iya bayar da abin da ka hana, kuma dukiyar mawadata ba ta da wani amfani a kanka.", "Bayan sallamar sallar farilla.", "Annabi ﷺ ya fadi haka bayan kowace sallar farilla."),
        "dua_slaughtering" to DuaText("Lokacin Yanka Dabba", "Da sunan Allah, kuma Allah ne Mafi girma.", "Lokacin yanka ko yanka dabba.", "Annabi ﷺ yayi Bismillah da takbir a lokacin layya."),
        "dua_undressing" to DuaText("Lokacin Cire Tufafi", "Da sunan Allah.", "Lokacin cire tufafi (don ghusl ko canzawa).", "Ya zama allo tsakanin idanuwan aljani da al'aurar mutum."),
        "dua_ilbas_jadidan" to DuaText("Ganin Wani Cikin Sabbin Tufafi", "Sabo, rayuwa abin yabo kuma ku mutu a shahada.", "Akan ganin dan uwa musulmi sanye da sabbin kaya.", "Annabi ﷺ yayi wannan addu'ar akan ganin Umar (RA) sanye da sabbin kaya."),
        "dua_hajj_la_riya" to DuaText("Hajjin Bana Bajewa", "Ya Allah (Ka sanya shi) Hajji mara fa'ida, ba neman suna.", "Domin ikhlasi wajen yin niyyar aikin Hajji.", "Annabi ﷺ yayi wannan addu'ar a lokacin aikin Hajji."),
        "dua_q_muslimayni_laka" to DuaText("Addu'ar Ibrahim da Ismail (AS)", "Ya Ubangijinmu! Ka nuna mana ibadun mu ka karbi tubanmu. Lalle Kai ne Mai karɓar tũba, Mai jin ƙai.", "Addu'ar mika wuya ga kai da zuri'ar sa.", "Addu'ar da aka yi yayin gina Ka'aba."),
        "dua_q_iftah_baynana" to DuaText("Dua na Shu'aib (AS) - Alkali Tsakanin Mu", "Ya Ubangijinmu, Ka yi hukunci tsakaninmu da mutanenmu da gaskiya, kuma Kai ne Mafificin alkalai.", "Domin hukunci tsakanin gaskiya da karya.", "Addu'ar Shu'aibu (AS) lokacin da mutanensa suka karyata shi."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) - Bai Taba Mai Taimakon Masu Laifi ba", "Ya Ubangiji, saboda ni'imar da Ka yi mini, ba zan kasance mai taimakon masu laifi ba.", "Godiya ga ni'imomin Allah da alkawarin rashin taimakon azzalumai.", "Mubaya'ar Musa (AS) bayan tuba."),
        "dua_q_nuh_unsurni" to DuaText("Dua na Nuhu (AS) - Ka Taimake Ni, Sun Karyata Ni", "Ubangijina, ka taimake ni, gama sun ƙaryata ni.", "Lokacin da mutane suka ƙaryata ku, kuma suka ƙaryata game da gaskiya.", "Addu'ar Nuhu (AS), wanda aka amsa."),
        "dua_q_ihkum_bil_haqq" to DuaText("Ubangijina, Ka yi hukunci da gaskiya", "Ubangijina, ka yi hukunci da gaskiya. Kuma Ubangijinmu Shi ne Mafi rahamah, ana neman taimakonSa a kan abin da kuke siffantawa.", "Ta fuskar karya da zargin karya.", "Addu'ar Annabi ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Mafaka Daga Murkushe Bashi Da Makiya", "Ya Allah ina neman tsarinka daga cin bashi, da galabaita a hannun makiya, da shelar makiya.", "Kariya daga nauyin bashi da mamayar makiya.", "Annabi ﷺ ya kasance yana neman tsari daga wadannan abubuwa."),
        "dua_faqr_qillah_dhillah" to DuaText("Gudun Hijira Daga Talauci Da Kaskanci", "Ya Allah ina neman tsarinka daga talauci da karanci da wulakanci da zalunci ko a zalunce ka.", "Don tsira daga wahala, so da wulakanci.", "Matsuguni da Annabi ya koyar ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Gafara, Yi Rahma, Jagora, Warkar, Azurtawa", "Ya Allah ka gafarta mini, ka yi mani rahama, ka shiryar da ni, ka ba ni lafiya, ka azurta ni.", "Annabi ﷺ ya koyar da wannan dua, tare da addu'a, ga sababbin musulmai.", "Annabi ﷺ ya ce: wadannan kalmomi sun tattaro muku duniya da lahira."),
        "dua_ruku_laka_raka_tu" to DuaText("A cikin Ruku - Gareki Na Ruku'u", "Ya Allah, gare Ka na rusuna, gare ka na yi imani, kuma gare ka na sallama. Jina, da ganina, da hankalina, da ƙasusuwana da jijiyoyina sun ƙasƙantar da kai a gabanka.", "A cikin ruku'u (musamman a cikin sallolin nafila).", "Annabi ﷺ ya karanta wannan a cikin ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("A cikin Sujood - Gare Ka Na yi Sujada", "Ya Allah, gare Ka na yi sujada, gare ka na yi imani, kuma gare ka na sallama. Fuskata ta yi sujada ga wanda ya halicce ta, Ya siffata ta, kuma Ya fitar da jinta da ganinta. Albarka ta tabbata ga Allah, Mafificin masu halitta.", "A cikin sujood (musamman a cikin sallolin nafila).", "Annabi ﷺ ya karanta wannan a cikin sujood."),
        "dua_ruku_sujood_subhanaka" to DuaText("Tsarki ya tabbata a gare Ka, Ubangijinmu - Ka gafarta mini", "Tsarki ya tabbata gareka, Ya Allah Ubangijinmu, kuma godiya ta tabbata gareka. Ya Allah ka gafarta mini.", "A cikin ruku da sujood.", "Aisha (RA): Annabi ﷺ ya yawaita fadin haka a ruku'u da sujud."),
        "dua_q_musa_li_akhi" to DuaText("Addu'ar Musa (AS) - Ka Gafarta Mani Da Dan'uwana", "Ubangijina Ka gafarta mini ni da dan uwana, kuma Ka shigar da mu a cikin rahamarKa, lallai Kai ne Mafi rahamar masu rahama.", "Afuwa ga kansa da kaninsa ko masoyinsa.", "Musa (AS) Haruna (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Ina Dankawa Al'amarina Ga Allah", "Kuma na jingina al'amarina ga Allah. Lallai Allah Mai gani ne ga bayinSa.", "Lokacin da mutane ke adawa da ku kuma dole ne a bar al'amarin ga Allah.", "Maganar muminai daga mutanen Fir'auna; Sai Allah Ya tsare shi daga munanan makircinsu."),
        "dua_q_hawariyyun" to DuaText("Dua na Almajirai - Ka Rubuto Mu Tare da Shaidu", "Ya Ubangijinmu, mun yi imani da abin da Ka saukar, kuma mun bi Manzo, sai ka rubuta mu a cikin masu shaida.", "Domin tsayuwa da imani da bin Manzo.", "Addu'ar almajiran Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Addu'ar Ibrahim (AS) - Kar Ka Bani kunya", "Kuma kada ka kunyata ni a ranar da ake tayar da su.", "Domin tsira daga wulakanci ranar kiyama.", "Addu'ar Ibrahim (AS) don Lahira."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar - A gare ku na yi azumi", "Ya Allah domin kai na yi azumi kuma da arzikinka na yi buda baki.", "Lokacin buda baki (fitar dua sanannu).", "Annabi ﷺ ya fadi haka a buda baki. Ruwaya ce ta mursal da wasu ruwayoyi suka karfafa; karanta shi a buda baki shine aikin Hanafiyya da mafiya rinjaye."),
        "dua_iftar_ibn_umar" to DuaText("Iftar — Ta Rahmarka Mai Girma, Ka Gafarta Mani", "Ya Allah ina rokonka da rahamarka wacce ta yalwaci dukkan komai ka gafarta mini.", "A buda baki – Abdullahi bn Amr (RA) yayi wannan addu’ar; ba a kore addu'ar mai azumi a buda baki.", "HADISI: Ba a kore addu’ar mai azumi a lokacin buda baki."),
        "dua_inni_saim" to DuaText("Lokacin Fuskanci Yayin Azumi", "Ina azumi, ina azumi.", "Lokacin da wani ya zage ku ko ya yi jayayya da ku yayin azumi.", "Annabi ﷺ ya ce: Azumi garkuwa ne, don haka kada mai azumi ya yi maganar batsa ko ya yi jahilci – idan wani ya yi husuma, ka fadi haka sau biyu."),
        "dua_eid_takbeer" to DuaText("Takbii a Hanyar Idi", "Allah shi ne mafi girma, Allah ne mafi girma, babu abin bautawa da gaskiya sai Allah, kuma Allah ne Mafi girma, Allah ne Mafi girma, kuma dukkan godiya ta tabbata ga Allah.", "Tun daga daren ganin wata har zuwa Sallar Idi, musamman a kan hanyar zuwa filin Idi.", "Umurnin Alqur'ani: 'domin ku cika ƙidayar, kuma ku yi shelar girman Allah' (al-Baqarah 2:185). Ibn Mas'ud (RA) ya fadi wannan takbir."),
        "dua_ahsin_aqibatana" to DuaText("Ka Sanya Karshen Mu Yayi Kyau A Dukkan Al'amuranmu", "Ya Allah ka kyautata karshen mu a dukkan al'amura, ka kare mu daga wulakanci duniya da azaba a lahira.", "Domin sakamako mai kyau a cikin kowane lamari.", "Duk wanda yayi wannan addu'ar kuma ya mutu kafin a jarraba shi ya mutu (amince daga fitina)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Ina neman falalarka da rahamarka", "Ya Allah ina rokonka falalarka da rahamarka, domin babu mai mallakarsu sai kai.", "Lokacin neman arziki da rahama.", "Baƙi sun zo wurin Annabi ﷺ lokacin da babu abinci; yayi wannan addu'ar, sai ga kyauta ta iso."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Kalmomin Koyarwa ga Badawiyya", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Allah ne Mafi girma, mai girma. Gõdiya ta tabbata ga Allah. Tsarki ya tabbata ga Allah Ubangijin talikai. Kuma bãbu wani ƙarfi, kuma bãbu wani ƙarfi fãce a wurin Allah, Mabuwãyi, Mai hikima.", "Cikakken jimlar zikiri da dua - wanda aka koya wa Badawiyya.", "Bayan haka sai aka koya masa cewa 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Gafarta Abinda Na Aiko Gaba da Bayansa", "Ya Allah Ka gafarta mini zunubban da na aikata gaba da baya da abin da na aikata a boye da abin da na aikata a bayyane, da wuce gona da iri da abin da Ka fi ni sani. Kai ne mai kawo gaba kuma mai mayarwa; babu abin bautawa face Kai.", "Bayan tashahud da salawat, kafin sallama.", "Annabi ﷺ ya karanta wannan a karshen sallah, tsakanin tashahudu da sallama."),
        "dua_jiddi_wa_hazli" to DuaText("Ka Gafarta Mani Tsanani Da Nishaɗina", "Ya Allah Ka gafarta mini zunubban da na aikata na tsanani da izgili, bisa kuskure da ganganci - kuma duk yana cikina.", "Gafara ga kowane irin zunubi, sananne da wanda ba a sani ba.", "Cikakken istighfar Annabi ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Bayan Ruku - Yabo Cika Sammai", "Ya Ubangijinmu, Gõdiya ta tabbata a gare Ka, Mai cika sammai, kuma Ka cika ƙasa, kuma Ka cika abin da Kake so daga bãyan wancan.", "Bayan an tashi daga ruku, tare da 'Rabbana lakal-hamd'.", "Annabi ﷺ ya fadi haka akan tashi daga ruku."),
        "dua_istiftah_kabira" to DuaText("Allah ne Mafi girma, Gõdadde", "Allah ne Mafi girma, mai girma. Gõdiya ta tabbata ga Allah. kuma tsarki ya tabbata ga Allah safe da yamma.", "Lokacin fara sallah (nau'i ɗaya na yabon buɗewa).", "Annabi ﷺ ya ce: an bude mata kofofin sama."),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) - Na Koka Ga Allah Kawai", "Ina korafin bacin rai da bacin raina ga Allah kadai.", "Cikin tsananin bakin ciki da rabuwa.", "Ya'qub (AS) ya faxi haka a cikin rabuwa da Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah ne Mafificin Majiɓinci", "Allah ne Mafificin Majiɓinci, kuma Shi ne Mafi rahamar Masu jin ƙai.", "Lokacin aika yara ko masoya akan tafiya.", "Yakub (AS) ya fadi haka ne a lokacin da yake dankawa Allah."),
        "dua_q_aqraba_rashada" to DuaText("Ubangijina Kayi Mani Kusa Da Dama", "Tsammãni Ubangijĩna Ya shiryar da ni zuwa ga abin da yake mafi kusanta daga wannan zuwa ga aiki na ƙwarai.", "Lokacin neman ingantacciyar hanya a wani lamari.", "An ce wa Annabi ﷺ ya fadi haka idan ya manta."),
        "dua_q_sawa_as_sabil" to DuaText("Addu'ar Musa (AS) - Ka Shiryar da Ni Hanya madaidaiciya", "Tsammãni Ubangijina Ya shiryar da ni zuwa ga hanya madaidaiciya.", "Lokacin tashi kan sabon tafiya ko hanyar da ba a sani ba.", "Musa (AS) ya faxi haka yayin da ya juya ga Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Kada Ka Sanya Ni Cikin Azzalumai", "Ya Ubangijina, kada Ka sanya ni a cikin mutane azzalumai.", "Addu'ar neman Allah ya nisantar da azzalumai.", "Addu'ar neman Allah ya nisantar da azzalumai."),
        "dua_q_do_not_make_us_trial" to DuaText("Kar Ka Sanya Mu Jaraba", "Ya Ubangijinmu, kada Ka sanya mu fitina ga kafirai, kuma Ka gafarta mana, Ya Ubangijinmu. Lalle ne Kai, Kai ne Mabuwãyi, Mai hikima.", "Addu'ar Ibrahim (AS) da Sahabbansa.", "Addu'ar Ibrahim (AS) da Sahabbansa."),
        "dua_morning_witness" to DuaText("Shaidar Safiya zuwa Tauhid", "Ya Allah na shiga safiya ina kira gare Ka, Ma'abocin Al'arshinKa, da Mala'ikunKa da dukkan halittunKa, su shaida cewa Kai ne Allah, babu abin bautawa da gaskiya sai Kai, Shi kadai, ba Shi da abokin tarayya, kuma Muhammadu ﷺ bawanka ne kuma ManzonKa ne.", "Ruwayar ta yi nuni da fadinsa sau hudu da safe.", "Ruwayar ta yi nuni da fadinsa sau hudu da safe."),
    )
}
